package com.hiretrack.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;@Entity @Table(name="applications") public class JobApplication{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@Column(nullable=false)private String companyName;@Column(nullable=false)private String jobRole;private String jobType;private String location;@Column(length=1000)private String jobLink;private BigDecimal salary;@Column(nullable=false)private String status="APPLIED";private LocalDate appliedDate;private LocalDate deadline;@Column(length=4000)private String description;private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public User getUser(){return user;}public void setUser(User v){user=v;}public String getCompanyName(){return companyName;}public void setCompanyName(String v){companyName=v;}public String getJobRole(){return jobRole;}public void setJobRole(String v){jobRole=v;}public String getJobType(){return jobType;}public void setJobType(String v){jobType=v;}public String getLocation(){return location;}public void setLocation(String v){location=v;}public String getJobLink(){return jobLink;}public void setJobLink(String v){jobLink=v;}public BigDecimal getSalary(){return salary;}public void setSalary(BigDecimal v){salary=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public LocalDate getAppliedDate(){return appliedDate;}public void setAppliedDate(LocalDate v){appliedDate=v;}public LocalDate getDeadline(){return deadline;}public void setDeadline(LocalDate v){deadline=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public LocalDateTime getCreatedAt(){return createdAt;}}